export function applyNewWater(host,ids,rgb,meta,m){const r={applied:false,written:0,reason:'invalid'};if(!meta||!m||meta.sourceSHA!==m.sourceSHA||meta.verified!==true||meta.conflict||!Array.isArray(meta.camera)||meta.camera.length!==4||!Number.isFinite(meta.timeMs)||ids.length!==m.count||rgb.length!==m.frames*m.count*3)return r;const[cx,cy,w,h]=meta.camera;if(host.length!==w*h*4||cx<0||cy<0||cx+w>3072||cy+h>1024)return r;if(!meta.enabled||meta.rest)return{...r,reason:'off-rest'};const phase=Math.floor(((meta.timeMs%6000)+6000)%6000/50);for(let i=0;i<ids.length;i++){const x=ids[i]%3072-cx,y=Math.floor(ids[i]/3072)-cy;if(x<0||y<0||x>=w||y>=h)continue;const d=(y*w+x)*4,s=(phase*ids.length+i)*3;for(let k=0;k<3;k++)host[d+k]=rgb[s+k];r.written++}return{...r,applied:true,reason:'new-water',phase}}
